export const settleCleaningPackageContractHeaderIdempotencyKeyMin = 8;
export const settleCleaningPackageContractHeaderIdempotencyKeyMax = 160;



export const SettleCleaningPackageContractHeader = zod.object({
  "Idempotency-Key": zod.string().min(settleCleaningPackageContractHeaderIdempotencyKeyMin).max(settleCleaningPackageContractHeaderIdempotencyKeyMax)
})

export const settleCleaningPackageContractBodyAmountExclusiveMin = 0;

export const settleCleaningPackageContractBodyOperationKeyMin = 8;
export const settleCleaningPackageContractBodyOperationKeyMax = 160;

export const settleCleaningPackageContractBodyAllocationsItemAmountExclusiveMin = 0;




export const SettleCleaningPackageContractBody = zod.object({
  "contractId": zod.number().optional().describe('Legacy single-contract shortcut; allocations is preferred'),
  "invoiceId": zod.number().nullish(),
  "amount": zod.number().gt(settleCleaningPackageContractBodyAmountExclusiveMin),
  "paymentMethod": zod.string(),
  "operationKey": zod.string().min(settleCleaningPackageContractBodyOperationKeyMin).max(settleCleaningPackageContractBodyOperationKeyMax),
  "depositId": zod.number().nullish(),
  "date": zod.string().optional(),
  "notes": zod.string().optional(),
  "allocations": zod.array(zod.object({
  "contractId": zod.number(),
  "amount": zod.number().gt(settleCleaningPackageContractBodyAllocationsItemAmountExclusiveMin),
  "invoiceId": zod.number().nullish()
})).min(1).optional()
})

